TLM.f("Sancti/10-09",{"officium":"S. Joannis Leonardi Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Eccli 42:15-16"},{"k":"text","la":"In sermónibus Dómini ópera ejus: sol illúminans per ómnia respéxit, et glória Dómini plenum est opus ejus."},{"k":"ref","la":"Ps 95:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: cantáte Dómino, omnis terra."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In sermónibus Dómini ópera ejus: sol illúminans per ómnia respéxit, et glória Dómini plenum est opus ejus."}],"Oratio":[{"k":"text","la":"Deus, qui beátum Joánnem Confessórem tuum ad fidem in géntibus propagándam mirabíliter excitáre dignátus es, ac per eum in erudiéndis fidélibus novam in Ecclésia tua famíliam congregásti: da nobis fámulis tuis; ita ejus institútis profícere, ut prǽmia consequámur ætérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"2 Cor 4:1-6, 15-18"},{"k":"text","la":"Fratres: Habéntes administratiónem juxta quod misericórdiam consecúti sumus, non defícimus, sed abdicámus occúlta dedécoris, non ambulántes in astútia, neque adulterántes verbum Dei, sed in manifestatióne veritátis commendántes nosmetípsos ad omnem consciéntiam hóminum coram Deo. Quod si étiam opértum est Evangélium nostrum: in iis, qui péreunt, est opértum: in quibus Deus hujus sǽculi excæcávit mentes infidélium, ut non fúlgeat illis illuminátio Evangélii glóriæ Christi, qui est imágo Dei. Non enim nosmetípsos prædicámus, sed Jesum Christum Dóminum nostrum: nos autem servos vestros per Jesum: quóniam Deus, qui dixit de ténebris lucem splendéscere, ipse illúxit in córdibus nostris ad illuminatiónem sciéntiæ claritátis Dei, in fácie Christi Jesu. Omnia enim propter vos: ut grátia abúndans, per multos in gratiárum actione, abúndet in glóriam Dei. Propter quod non deficimus: sed licet is, qui foris est, noster homo corrumpátur: tamen is, qui intus est, renovatur de die in diem. Id enim, quod in præsenti est momentáneum et leve tribulatiónis nostræ, supra modum in sublimitáte ætérnum glóriæ pondus operátur in nobis, non contemplántibus nobis quæ vidéntur, sed quæ non vidéntur. Quæ enim vidéntur, temporália sunt: quæ autem non vidéntur, ætérna sunt."}],"Graduale":[{"k":"ref","la":"Ps 72:21; 68:10"},{"k":"text","la":"Inflammátum est cor meum, et renes mei commutáti sunt: zelus domus tuæ comédit me."},{"k":"ref","la":"Isa 49:2"},{"k":"text","la":"Pósuit os meum quasi gládium acutum: in umbra manus suæ protéxit me, et pósuit me sicut sagíttam eléctam. Allelúja, allelúja."},{"k":"ref","la":"Ps 70:7"},{"k":"text","la":"Tamquam prodígium factus sum multis: et tu adjútor fortis, Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 51:10"},{"k":"text","la":"Sicut olíva fructífera in domo Dei, speravi in misericórdia Dei in ætérnum: et in sǽculum sǽculi. Allelúja"},{"k":"ref","la":"Ps 61:8"},{"k":"text","la":"In Deo salutáre meum, et glória mea: Deus auxílii mei, et spes mea in Deo est. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 54:3-4; 64:17"},{"k":"text","la":"Contristátus sum in exercitatióne mea: et conturbátus sum a voce inimíci, et a tribulatióne peccatóris."},{"k":"text","la":"Quóniam declinavérunt in me iniquitátes: et in ira molésti erant mihi.","mark":"V"},{"k":"text","la":"Ego autem ad Deum clamávi: et Dóminus salvábit me.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"ref","la":"Col 1:25"},{"k":"text","la":"Christi factus sum ego miníster secúndum dispensatiónem Dei, quæ data est mihi, ut ímpleam verbum Dómini."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, oblatiónem mundam salutáris hóstiæ: et præsta; ut, intercedénte beáto Joánne Confessóre tuo, úbique géntium júgiter offerátur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Phil 3:7"},{"k":"text","la":"Quæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum detriménta."}],"Postcommunio":[{"k":"text","la":"Pretiósi córporis, et sánguinis tui sacris refécti mystériis, Dómine, adprecámur: ut beáti Joánnis Confessóris tui exémplo, studeámus confitéri quod crédidit, et ópere exercére quod dócuit:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"77af0abea46e91ff":{"t":"Sir 42, 15-16, Ps 95, 1\n(Sir 42, 15-16) Božje je rijeci ostvario svojim djelima. Poput sunca što sve obasjava rad je njegov pun slave Gospodnje. (Ps 95, 1) Pjevajte Gospodinu pjesmu novu, pjevaj Gospodinu, sva zemljo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 42, 15-16) Božje je rijeci ostvario svojim djelima. Poput sunca što sve obasjava rad je njegov pun slave Gospodnje.","kn":"(Crkv. 42, 15-16).. Djela .su njegova riječ Božja, .poput sunca, što sve obasjava, rad je njegov Sv. Ivan Leonardo , 9. X. pun slave, Gospodnje. (Ps. 95. 1) Pjevajte Gospodinu pjesmu novu, pjevaj Gospodinu, sva , zemljo! Slava Ocu,.;., Djela .. .","knRef":"Kniewald 1942, str. 732–733 (snimka 367) (OCR)"},"2e28536f5802b343":{"t":"<i>Pomolimo se</i>.\nBože, koji si se udostojao čudesno pozvati blaženog Ivana priznavaoca svoga da širi vjeru među narodima i po njemu sabrao u svojoj Crkvi novu obitelj za poučavanje vjernih, daj nama, slugama svojim, da se tako koristimo njegovim uputama te postignemo vječne nagrade.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si se dostojao' divno potaknuti blaženog Ivana, prlznavaoca svoga, da propovijeda Vjeru narodima, i koji ,si pO njemu sabrao. msvojoj Crkvi novu porodicu za pouku vjermika, podaj, da mi, tvoji sluge, njegovim poticajem^tako uznapredujemo, te dostignemo vječne nagrade. Po G- n.","knRef":"Kniewald 1942, str. 732–733 (snimka 367) (OCR)"},"9c0ac8606e0f6866":{"t":"2 Kor 4, 1-6 i 15-18\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, ovu službu vršimo radi milosrđa koje smo postigli. Ne malakšemo nego se odrekosmo nečasnom tajnom postupanja, jer ne živimo lukavo i ne iskrivljujemo riječ Božju, nego je objavljivanjem istine preporučujemo svakoj ljudskoj savjesti pred Bogom. A ako je i pokriveno naše Evanđelje, u onima je pokriveno koji propadaju. Bog je ovoga svijeta [napomena M.B. huius saeculi doslovno znači: ovog vijeka] zaslijepio njihove nevjerne pameti da im ne zasja svjetlo Evanđelja o slavi Kristovoj koji je slika Božja. A mi ne propovijedamo sami sebe, nego Krista Isusa Gospodina našega, a sebe kao sluge vaše poradi Isusa. Bog, koji reče: Neka u tami grane svjetlo, obasjao je naša srca da budu rasvijetljena spoznajom slave Božje po licu Krista Isusa. Sve je ovo radi vas da se na slavu Boga obilna milost izlije na mnoge. Zato ne malakšemo, nego ako se naš izvanji čovjek i raspada, unutrašnji se obnavlja iz dana u dan. Naša sadašnja časovita i laka nevolja donosi nam prekomjernu, izobilnu, vječnu i od svega vrjedniju slavu, jer mi ne marimo za ono što se vidi nego za ono što se ne vidi. Ono što se vidi kratkotrajno je, a ono što se ne vidi vječno je.","kn":"Čitanje poslanice bi. Pavla apostola Kormćanlma (II 4 i-6 i 15-18). Braćo! Imajući ovu službu radi milosrđa, koje smo postigli,' ne malakšemo,, nego se odrekosmo sramotnoga tajnoga postupanja, jer n živimo lukavo, niti izopačujemo riječ Božju, mego se javljanjem istine preporučujemo svakoj ljudskoj savjesti pred Bogom; Ali ako je i pokriveno naše evanđelje, u onima je pokriveno, koji propadaju, u kojima bog ovoga svijeta o, slijepi mišljenje nevjernika, da im ne zasvijetli svijetlo evanđelja^o slavi Kristovoj, koji je' .»lika Božja. Jer sami se e ne propovijedamo, nego Krista Isusa kaO Gospođ.i,na, a sebe kao sluge vaše poradi .Isusa. Jer Bog, koji reče: Iz tame neka zasvijetli svijetlo, on, je zasvijetlio u srcima našim, da svijetli poznanje slave Božje u osobi Isusa Krista. Jer. jb sve poradi vas da se milost umnoži većim brojem (vjernika) i dade izo bilnu zahvalu na slavu Božju. Zato ne malakšemo. nego alko se naš izvanji čovjek i raspada, ali se nas unutrašnji obnavlja od danau dah. Jer naša sadašnja i časo-Vita laka nevolja donosi nam prekomjernu, izobilnu, vječnu) od svega pretežniju slavu,, budući da mi ne marimo za ono, što se vidi, nego za ono, Što se ne vidi, jer je ono, što še vidi, za vrijeme, a ono, što se ne vidi, vječno.","knRef":"Kniewald 1942, str. 732–733 (snimka 367) (OCR)"},"9043eeda82d25ce1":{"t":"Ps 72, 21, Ps 68, 10, Iz 49, 2\n(Ps 72, 21) Ražeglo se srce moje i usplamtjelo je tijelo moje: (Ps 68, 10) izjeda me revnost za domom tvojim. (Iz 49, 2) Učinio je moja usta kao oštar mač, zaštito me okriljem svoje ruke i učinio me izabranom strijelom.\n\nPs 70, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nMnogima sam izgledao kao čudo, jer si mi ti bio jaki zaštitnik. <i>Aleluja</i>.","kn":"(Ps. 72, 21; 68, 10). Raeplamtilo se srce moje i izmijenjena je moja nutrinja: izjeda me revnost za tvoj dom. (Izai. 49, 2) Učinio je usta moja kao oštri mač; zaštitio me sjenom ruke svoje i učinio me kao izabranu strjelicu.\n\nAleluja, aleluja (Ps, 70, 7) Mnogi su mi se divili, a ti si moj jaki zaštitnik, aleluja.","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"7badc8f6b977af1e":{"t":"Kol 1, 25\nPostao sam Kristov službenik po Božjoj odredbi koja se odnosi na mene da ispunim riječ Gospodnju.","kn":"(Kol. 1, 25). Postadoh Kristovim, slugom po službi, koju mi je Bog dao, da, ispunim riječ Božju.","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"1b5ee378b1158f54":{"t":"Primi, Gospodine, čisti prinos spasonosnog dara i daj da se po zagovoru blaženog Ivana priznavaoca tvoga neprestano prikazuje kod svih naroda.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, čisti prinos spasonosne žrtve i podaj, da se odvjetovanjem blaženog Ivana, tvoga priznavaoca, neprestano prinosi na čitavom svijetu. Po G. n.","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"c28510d7f3861340":{"t":"Fil 3, 7\nŠto sam prije smatrao za dobit to radi Krista smatram za štetu.","kn":"(EiliP- 3, 7). Sto mi bijaše, dobitak, to sam smatrao za štetu radi Krista. -","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"91ac56978bf00af5":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni svetim tajnama dragocjenog tijela i krvi, tvoje, molimo, Gospodine, da po primjeru blaženog Ivana priznavaoca tvoga nastojimo priznavati što je on vjerovao i djelom izvršavati što je učio:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ojačani svetim tajnama dragocjenog tijela i krvi tvoje, molimo te. Gospodine, da n - sljedujući primjer blaženog Ivana, priznavaoca Moga, n^jimo priznavati što je vjerovao, i. djelom izvršavati što je učio, koji zivis i kraljujes .... sviiet 1 dvorski “ pokore, samo- ^iU^1’\"r^;^rn7^rbi’o7e\"fn^^^^^^ - «vo.","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"}}});
